1	import test from "node:test";
2	import assert from "node:assert/strict";
3	import { filterOrders } from "../src/order-filter.mjs";
4	const orders = [{ id: "A-1", customer: "Alice", status: "paid" }, { id: "B-2", customer: "Bob", status: "pending" }];
5	test("空关键词保留全部订单", () => {
6	  assert.deepEqual(filterOrders(orders, { keyword: "" }), orders);
7	});

1	// 空关键词不限制搜索，状态条件与关键词条件同时生效。
2	export function filterOrders(orders, { keyword = "", status = "all" } = {}) {
3	  const query = keyword.trim().toLowerCase();
4	  return orders.filter(order => (status === "all" || order.status === status) && (!query || `${order.id} ${order.customer}`.toLowerCase().includes(query)));
5	}
